// Port of chacha20 =0.10.0 `src/rng.rs` (feature `rng`, which rand 0.10.1's `std_rng` enables).
// PORT: `impl_chacha_rng!` is `impl_chacha_rng(name, rounds)`, a function returning the generator class;
// `ChaCha8Rng`/`ChaCha12Rng`/`ChaCha20Rng` are its three expansions. u64 is `bigint`, u128 is `bigint`.
import type { Debug, Fmt } from "../../std/fmt.ts";
import { Ok, type Result } from "../../std/result.ts";
import { Rng_for_TryRng, type CryptoRng, type Infallible, type Rng as Rng_ } from "../rand_core/lib.ts";
import { BlockRng, type Generator } from "../rand_core/block.ts";
import type { SeedableRng } from "../rand_core/seedable_rng.ts";
import { SeedableRng_provided } from "../rand_core/seedable_rng.ts";
import { Word_u32 } from "../rand_core/word.ts";
import { ChaChaCore, R12, R20, R8, type Rounds } from "./lib.ts";
import { Backend } from "./backends/soft.ts";
import { Legacy } from "./variants.ts";

const U64_MASK = 0xffff_ffff_ffff_ffffn;

/// Seed value used to initialize ChaCha-based RNGs.
export type Seed = Uint8Array; // [u8; 32]

/// Serialized RNG state.
export type SerializedRngState = Uint8Array; // [u8; 49]

/// Number of 32-bit words per ChaCha block (fixed by algorithm definition).
export const BLOCK_WORDS = 16;

/// The number of blocks generated by each call to the backend's `generate`.
const BUF_BLOCKS = 4;
/// Buffer size in words, i.e. `BLOCK_WORDS * BUF_BLOCKS`.
const BUFFER_SIZE = BLOCK_WORDS * BUF_BLOCKS;

// impl<R: Rounds, V: Variant> SeedableRng for ChaChaCore<R, V>
// PORT: generic over `R`; `V` is `Legacy`, the only variant the `rng` feature pairs with a seed.
export function SeedableRng_for_ChaChaCore(R: Rounds): SeedableRng<ChaChaCore<bigint>> {
  return {
    Seed_default: () => new Uint8Array(32),

    // crate: chacha20-0.10.0/src/rng.rs:39 from_seed
    from_seed(seed: Seed): ChaChaCore<bigint> {
      return ChaChaCore.new_internal(R, Legacy, seed, new Uint8Array(8));
    },
  };
}

// impl<R: Rounds, V: Variant> Generator for ChaChaCore<R, V>
// (`type Output = [u32; BUFFER_SIZE]`)
declare module "./lib.ts" {
  interface ChaChaCore<Counter> extends Generator<number> {
    generate(buffer: number[]): void;
  }
}

// crate: chacha20-0.10.0/src/rng.rs:49 generate
ChaChaCore.prototype.generate = function <Counter>(this: ChaChaCore<Counter>, buffer: number[]): void {
  // PORT: the `cfg_if!` takes its final `else` arm, the soft backend (see backends.ts).
  new Backend(this).gen_ks_blocks(buffer);
};

// crate-skip: chacha20-0.10.0/src/rng.rs:97 drop cfg(feature = "zeroize"): off in rand's dependency

/// Interface of the `impl_chacha_rng!` expansions.
export interface ChaChaRng extends CryptoRng {
  get_word_pos(): bigint;
  set_word_pos(word_offset: bigint): void;
  set_block_pos(block_pos: bigint): void;
  get_block_pos(): bigint;
  set_stream(stream: bigint): void;
  get_stream(): bigint;
  get_seed(): Uint8Array;
  serialize_state(): SerializedRngState;
  eq(rhs: ChaChaRng): boolean;
}

function impl_chacha_rng(Rng: string, rounds: Rounds) {
  /// A cryptographically secure random number generator that uses the ChaCha stream cipher.
  ///
  /// See the [crate docs][crate] for more information about the underlying stream cipher.
  ///
  /// This RNG implementation uses a 64-bit counter and 64-bit stream identifier (a.k.a nonce).
  /// A 64-bit counter over 64-byte (16 word) blocks allows 1 ZiB of output before cycling,
  /// and the stream identifier allows 2<sup>64</sup> unique streams of output per seed.
  /// Both counter and stream are initialized to zero but may be set via the `set_word_pos`
  /// and `set_stream` methods.
  return class ChaChaXRng implements ChaChaRng {
    constructor(public core: BlockRng<number, ChaChaCore<bigint>>) {}

    // impl SeedableRng for $Rng
    static Seed_default(): Seed {
      return new Uint8Array(32);
    }

    // crate: chacha20-0.10.0/src/rng.rs:142 from_seed
    static from_seed(seed: Seed): ChaChaXRng {
      const core = ChaChaCore.new_internal(rounds, Legacy, seed, new Uint8Array(8));
      return new ChaChaXRng(BlockRng.new(core, Word_u32, BUFFER_SIZE));
    }

    /** `SeedableRng::seed_from_u64` (provided). */
    static seed_from_u64(state: bigint): ChaChaXRng {
      return SeedableRng_provided.seed_from_u64(ChaChaXRng, state);
    }

    /** `SeedableRng::from_rng` (provided). */
    static from_rng(rng: Rng_): ChaChaXRng {
      return SeedableRng_provided.from_rng(ChaChaXRng, rng);
    }

    // impl TryRng for $Rng
    // crate: chacha20-0.10.0/src/rng.rs:154 try_next_u32
    try_next_u32(): Result<number, Infallible> {
      return Ok(this.core.next_word());
    }
    // crate: chacha20-0.10.0/src/rng.rs:158 try_next_u64
    try_next_u64(): Result<bigint, Infallible> {
      return Ok(this.core.next_u64_from_u32());
    }
    // crate: chacha20-0.10.0/src/rng.rs:162 try_fill_bytes
    try_fill_bytes(dest: Uint8Array): Result<void, Infallible> {
      this.core.fill_bytes(dest);
      return Ok(undefined);
    }

    // impl Rng (blanket impl over `TryRng<Error = Infallible>`)
    next_u32(): number {
      return Rng_for_TryRng.next_u32(this);
    }
    next_u64(): bigint {
      return Rng_for_TryRng.next_u64(this);
    }
    fill_bytes(dst: Uint8Array): void {
      Rng_for_TryRng.fill_bytes(this, dst);
    }

    // We use custom implementation of `PartialEq` because RNG states
    // may buffer different parts of the same keystream, while keeping
    // buffer cursor pointing towards the same keystream point.
    // crate: chacha20-0.10.0/src/rng.rs:177 eq
    eq(rhs: ChaChaRng): boolean {
      return (
        bytes_eq(this.get_seed(), rhs.get_seed()) &&
        this.get_stream() === rhs.get_stream() &&
        this.get_word_pos() === rhs.get_word_pos()
      );
    }

    // Custom Debug implementation that does not expose the internal state
    // crate: chacha20-0.10.0/src/rng.rs:188 fmt
    static fmt(_v: ChaChaXRng, _f: Fmt): string {
      return `${Rng} { ... }`;
    }

    /// Get the offset from the start of the stream, in 32-bit words.
    ///
    /// Since the generated blocks are 64 words (2<sup>6</sup>) long and the
    /// counter is 64-bits, the offset is a 68-bit number. Sub-word offsets are
    /// not supported, hence the result can simply be multiplied by 4 to get a
    /// byte-offset.
    // crate: chacha20-0.10.0/src/rng.rs:202 get_word_pos
    get_word_pos(): bigint {
      const state = this.core.core.state;
      let block_counter = (BigInt(state[13]!) << 32n) | BigInt(state[12]!);
      if (this.core.word_offset() !== 0) {
        block_counter = (block_counter - BigInt(BUF_BLOCKS)) & U64_MASK;
      }
      const word_pos = block_counter * BigInt(BLOCK_WORDS) + BigInt(this.core.word_offset());
      // eliminate bits above the 68th bit
      return word_pos & ((1n << 68n) - 1n);
    }

    /// Set the offset from the start of the stream, in 32-bit words. **This
    /// value will be erased when calling `set_stream()`, so call
    /// `set_stream()` before calling `set_word_pos()`** if you intend on
    /// using both of them together.
    ///
    /// As with `get_word_pos`, we use a 68-bit number. Since the generator
    /// simply cycles at the end of its period (1 ZiB), we ignore the upper
    /// 60 bits.
    // crate: chacha20-0.10.0/src/rng.rs:224 set_word_pos
    set_word_pos(word_offset: bigint): void {
      const index = Number(word_offset % BigInt(BLOCK_WORDS));
      const counter = word_offset / BigInt(BLOCK_WORDS);
      //self.set_block_pos(counter as u64);
      const state = this.core.core.state;
      state[12] = Number(counter & 0xffff_ffffn);
      state[13] = Number((counter >> 32n) & 0xffff_ffffn);
      this.core.reset_and_skip(index);
    }

    /// Sets the block pos and resets the RNG's index.
    ///
    /// The word pos will be equal to `block_pos * 16 words per block`.
    ///
    /// This can be used with either:
    /// * u64
    /// * [u8; 8] (little-endian)
    // crate: chacha20-0.10.0/src/rng.rs:242 set_block_pos
    set_block_pos(block_pos: bigint): void {
      this.core.reset_and_skip(0);
      this.core.core.set_block_pos(block_pos);
    }

    /// Get the block pos.
    // crate: chacha20-0.10.0/src/rng.rs:251 get_block_pos
    get_block_pos(): bigint {
      const counter = this.core.core.get_block_pos();
      const offset = this.core.word_offset();
      if (offset !== 0) {
        // PORT: release builds wrap on overflow (no overflow checks), hence the masks.
        return (((counter - BigInt(BUF_BLOCKS)) & U64_MASK) + BigInt(Math.floor(offset / 16))) & U64_MASK;
      } else {
        return counter;
      }
    }

    /// Set the stream ID and reset the `word_pos` to 0.
    // crate: chacha20-0.10.0/src/rng.rs:263 set_stream
    set_stream(stream: bigint): void {
      const state = this.core.core.state;
      state[14] = Number(stream & 0xffff_ffffn);
      state[15] = Number((stream >> 32n) & 0xffff_ffffn);
      this.set_block_pos(0n);
    }

    /// Get the stream number.
    // crate: chacha20-0.10.0/src/rng.rs:272 get_stream
    get_stream(): bigint {
      const state = this.core.core.state;
      const result = new Uint8Array(8);
      result.set(Word_u32.to_le_bytes(state[14]!), 0);
      result.set(Word_u32.to_le_bytes(state[15]!), 4);
      return u64_from_le_bytes(result);
    }

    /// Get the RNG seed.
    // crate: chacha20-0.10.0/src/rng.rs:282 get_seed
    get_seed(): Uint8Array {
      const seed = this.core.core.state.subarray(4, 12);
      const result = new Uint8Array(32);
      for (let i = 0; i < seed.length; i++) {
        result.set(Word_u32.to_le_bytes(seed[i]!), i * 4);
      }
      return result;
    }

    /// Serialize RNG state.
    ///
    /// # Warning
    /// Leaking serialized RNG state to an attacker defeats security properties
    /// provided by the RNG.
    // crate: chacha20-0.10.0/src/rng.rs:297 serialize_state
    serialize_state(): SerializedRngState {
      const seed = this.get_seed();
      const stream = u64_to_le_bytes(this.get_stream());
      const word_pos = u128_to_le_bytes(this.get_word_pos());

      const res = new Uint8Array(49);
      const seed_dst = res.subarray(0, 32);
      const stream_dst = res.subarray(32, 40);
      const word_pos_dst = res.subarray(40);

      seed_dst.set(seed);
      stream_dst.set(stream);
      word_pos_dst.set(word_pos.subarray(0, 9));

      // debug_assert_eq!(&word_pos[9..], &[0u8; 7]);

      return res;
    }

    /// Deserialize RNG state.
    // crate: chacha20-0.10.0/src/rng.rs:317 deserialize_state
    static deserialize_state(state: SerializedRngState): ChaChaXRng {
      const seed = state.subarray(0, 32);
      const stream = state.subarray(32, 40);
      const word_pos_raw = state.subarray(40);

      // Note that we use only 68 bits from `word_pos_raw`, i.e. 4 remaining bits
      // get ignored and should be equal to zero in practice.
      const word_pos_buf = new Uint8Array(16);
      word_pos_buf.set(word_pos_raw.subarray(0, 9));
      const word_pos = u128_from_le_bytes(word_pos_buf);

      const core = ChaChaCore.new_internal(rounds, Legacy, seed, stream);
      const res = new ChaChaXRng(BlockRng.new(core, Word_u32, BUFFER_SIZE));

      res.set_word_pos(word_pos);
      return res;
    }
  };
}

/** `impl_chacha_rng!(ChaCha8Rng, R8)` */
export const ChaCha8Rng = impl_chacha_rng("ChaCha8Rng", R8);
export type ChaCha8Rng = InstanceType<typeof ChaCha8Rng>;
/** `impl_chacha_rng!(ChaCha12Rng, R12)` */
export const ChaCha12Rng = impl_chacha_rng("ChaCha12Rng", R12);
export type ChaCha12Rng = InstanceType<typeof ChaCha12Rng>;
/** `impl_chacha_rng!(ChaCha20Rng, R20)` */
export const ChaCha20Rng = impl_chacha_rng("ChaCha20Rng", R20);
export type ChaCha20Rng = InstanceType<typeof ChaCha20Rng>;
export const debug_ChaCha8Rng: Debug<ChaCha8Rng> = (v, f) => ChaCha8Rng.fmt(v, f);
export const debug_ChaCha12Rng: Debug<ChaCha12Rng> = (v, f) => ChaCha12Rng.fmt(v, f);
export const debug_ChaCha20Rng: Debug<ChaCha20Rng> = (v, f) => ChaCha20Rng.fmt(v, f);

function bytes_eq(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

function u64_from_le_bytes(b: Uint8Array): bigint {
  let x = 0n;
  for (let i = 7; i >= 0; i--) x = (x << 8n) | BigInt(b[i]!);
  return x;
}

function u64_to_le_bytes(x: bigint): Uint8Array {
  const out = new Uint8Array(8);
  for (let i = 0; i < 8; i++) out[i] = Number((x >> BigInt(8 * i)) & 0xffn);
  return out;
}

function u128_from_le_bytes(b: Uint8Array): bigint {
  let x = 0n;
  for (let i = 15; i >= 0; i--) x = (x << 8n) | BigInt(b[i]!);
  return x;
}

function u128_to_le_bytes(x: bigint): Uint8Array {
  const out = new Uint8Array(16);
  for (let i = 0; i < 16; i++) out[i] = Number((x >> BigInt(8 * i)) & 0xffn);
  return out;
}
